const R2 = path.join(__dirname, "results_v2") + "/";
const R1 = path.join(__dirname, "results") + "/";
const INK = "1f2933";

const h1 = t => new Paragraph({ text: t, heading: HeadingLevel.HEADING_1, keepNext: true, spacing: { before: 260, after: 120 } });
const h2 = t => new Paragraph({ text: t, heading: HeadingLevel.HEADING_2, keepNext: true, spacing: { before: 170, after: 80 } });
const P  = t => new Paragraph({ children: [new TextRun(t)], spacing: { after: 140 }, alignment: AlignmentType.JUSTIFIED });
const bullet = t => new Paragraph({ text: t, bullet: { level: 0 }, spacing: { after: 50 }, alignment: AlignmentType.JUSTIFIED });
const P2 = (lead, t) => new Paragraph({ children: [new TextRun({ text: lead, bold: true }), new TextRun(t)], spacing: { after: 140 }, alignment: AlignmentType.JUSTIFIED });
const note = t => new Paragraph({ children: [new TextRun({ text: t, italics: true, color: "8a8f98" })], spacing: { after: 140 } });

function figure(path, w, h, caption) {
  const buf = fs.readFileSync(path);
  return [
    new Paragraph({ alignment: AlignmentType.CENTER, keepNext: true, keepLines: true, spacing: { before: 120, after: 40 },
      children: [new ImageRun({ type: "png", data: buf, transformation: { width: w, height: h } })] }),
    new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 180 },
      children: [new TextRun({ text: caption, italics: true, size: 18, color: INK })] }),
  ];
}
function cell(text, o = {}) {
  return new TableCell({ width: { size: o.w, type: WidthType.DXA },
    shading: o.head ? { fill: "0f9d8f" } : (o.alt ? { fill: "eef4f3" } : undefined),
    children: [new Paragraph({ alignment: o.center ? AlignmentType.CENTER : AlignmentType.LEFT, keepNext: !!o.keep,
      children: [new TextRun({ text, bold: !!o.head, color: o.head ? "ffffff" : INK, size: 16 })] })] });
}
function tableFrom(headers, rows, widths) {
  const hr = new TableRow({ tableHeader: true, cantSplit: true, children: headers.map((t, i) => cell(t, { w: widths[i], head: true, center: i > 0, keep: true })) });
  const trs = rows.map((r, ri) => new TableRow({ cantSplit: true, children: r.map((t, i) => cell(String(t), { w: widths[i], center: i > 0, alt: ri % 2, keep: ri < rows.length - 1 })) }));
  return new Table({ columnWidths: widths, width: { size: widths.reduce((a, b) => a + b), type: WidthType.DXA }, rows: [hr, ...trs] });
}

